.avue-main2 {
  position: absolute;
  left: 0;
  width: 100%;
}

.mDrawer{
 .el-card{
    width: 90%;
    margin: 20px auto;
    padding-bottom: 20px;
    box-shadow: 0 2px 12px 0 rgba(0,0,0,.1) !important;
    cursor: pointer;
    position: relative;
    overflow: visible;

    .dian{
      position: absolute;
      top: -3px;
      right: -3px;
      width: 10px;
      height: 10px;
      background: red;
      border-radius: 50%;
    }
  } 
  .item1{
    font-size: 14px;
    color: #2c3e50;
  }
  .item2{
    font-size: 14px;
    color: #666;
    margin: 5px 0;
  }
  .item3{
    font-size: 13px;
    color: #666;
  }
  ::v-deep .el-drawer__header{
    padding-top: 15px;
    padding-bottom: 15px;
    margin-bottom: 0;
    background: #fff;
    border-bottom: 1px solid #e7e7e7;
  }
}
